function syntheticHistory(symbol, interval, limit) {
  const step = INTERVALS[interval]; // ms
  const stepSec = step / 1000;
  const now = Date.now();
  const end = Math.floor(now / step) * step;
  const candles = [];
  for (let i = limit - 1; i >= 0; i--) {
    const startMs = end - i * step;
    const t = Math.floor(startMs / 1000);
    const open = priceAt(symbol, t);
    const close = priceAt(symbol, t + stepSec);
    const wick = 0.0008 + (hash(symbol + ":w" + t) % 1000) / 1000 * 0.0025;
    const high = Math.max(open, close) * (1 + wick);
    const low = Math.min(open, close) * (1 - wick * 0.9);
    const volume = 50 + (hash(symbol + ":v" + t) % 100000) / 100;
    candles.push({ time: t, open: round(open), high: round(high), low: round(low), close: round(close), volume: Math.round(volume) });
  }
  return candles;
}
