function syntheticTicker(symbol) {
  const now = Math.floor(Date.now() / 1000);
  const price = priceAt(symbol, now);
  const dayAgo = priceAt(symbol, now - 86400);
  let high = price, low = price;
  for (let i = 0; i <= 24; i++) {
    const p = priceAt(symbol, now - i * 3600);
    if (p > high) high = p;
    if (p < low) low = p;
  }
  return { price: round(price), changePct: Math.round((price / dayAgo - 1) * 10000) / 100, high: round(high), low: round(low), volume: Math.round(50000 + (hash(symbol + now) % 900000)) };
}
