export function searchSymbols(symbols, query, limit) {
  const q = query.trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
  if (!q) return symbols.slice(0, limit);
  const scored = [];
  for (const item of symbols) {
    const symbol = item.symbol;
    let score = -1;
    if (symbol === q) score = 0;
    else if (symbol.startsWith(q)) score = 1;
    else if (item.base.startsWith(q)) score = 2;
    else if (symbol.includes(q) || item.base.includes(q)) score = 3;
    if (score >= 0) scored.push([score, item]);
  }
  scored.sort((a, b) => a[0] - b[0] || a[1].symbol.localeCompare(b[1].symbol));
  return scored.slice(0, limit).map(([, item]) => item);
}
