import { parseSymbol } from "./market.js";
import { json, getCookie } from "./http.js";

const COOKIE = "ot_sid";
let schemaReady = false;

async function ensureSchema(db) {
  if (schemaReady) return;
  await db.prepare("CREATE TABLE IF NOT EXISTS watchlist (sid TEXT NOT NULL, symbol TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (sid, symbol))").run();
  schemaReady = true;
}

function cookieHeader(sid) {
  return `${COOKIE}=${sid}; Path=/; HttpOnly; SameSite=Lax; Max-Age=31536000`;
}

export async function handleWatchlist(request, env, url) {
  const path = url.pathname;
  if (!path.startsWith("/api/watchlist")) return null;
  const db = env.DB;
  if (!db) {
    if (request.method === "GET") return json({ storage: "local", symbols: [] });
    return json({ storage: "local", ok: true });
  }
  await ensureSchema(db);
  let sid = getCookie(request, COOKIE);
  const headers = {};
  if (!sid || sid.length < 8) {
    sid = crypto.randomUUID();
    headers["set-cookie"] = cookieHeader(sid);
  }
  if (request.method === "GET" && path === "/api/watchlist") {
    const { results } = await db.prepare("SELECT symbol FROM watchlist WHERE sid = ? ORDER BY created_at ASC").bind(sid).all();
    return json({ storage: "d1", symbols: results.map(r => r.symbol) }, 200, headers);
  }
  if (request.method === "POST" && path === "/api/watchlist") {
    let body;
    try { body = await request.json(); } catch { return json({ error: "invalid_body" }, 400); }
    const symbol = parseSymbol(body?.symbol);
    if (!symbol) return json({ error: "invalid_symbol" }, 400);
    const count = await db.prepare("SELECT COUNT(*) AS n FROM watchlist WHERE sid = ?").bind(sid).first();
    if ((count?.n ?? 0) >= 50) return json({ error: "watchlist_full" }, 409);
    await db.prepare("INSERT OR IGNORE INTO watchlist (sid, symbol, created_at) VALUES (?, ?, ?)").bind(sid, symbol, Date.now()).run();
    return json({ storage: "d1", ok: true, symbol }, 200, headers);
  }
  if (request.method === "DELETE" && path.startsWith("/api/watchlist/")) {
    const symbol = parseSymbol(decodeURIComponent(path.slice("/api/watchlist/".length)));
    if (!symbol) return json({ error: "invalid_symbol" }, 400);
    await db.prepare("DELETE FROM watchlist WHERE sid = ? AND symbol = ?").bind(sid, symbol).run();
    return json({ storage: "d1", ok: true }, 200, headers);
  }
  return json({ error: "method_not_allowed" }, 405);
}
```
