function connectStream() {
  disconnectStream();
  if (state.source === "synthetic") { startPolling("synthetic"); return; }
  const stream = `${state.symbol.toLowerCase()}@kline_${state.interval}`;
  const urls = [
    `wss://stream.binance.com:9443/ws/${stream}`,
    `wss://stream.binance.com/ws/${stream}`,
  ];
  const index = state.wsRetry % urls.length;
  state.wsRetry += 1;
  setConn("connecting");
  let ws;
  try { ws = new WebSocket(urls[index]); } catch { startPolling("polling"); return; }
  state.ws = ws;
  const openedAt = Date.now();
  ws.addEventListener("open", () => { setConn("live"); stopPolling(); });
  ws.addEventListener("message", (event) => {
    try {
      const msg = JSON.parse(event.data);
      if (msg && msg.e === "kline" && msg.k) applyKline(msg.k);
    } catch {}
  });
  ws.addEventListener("error", () => { try { ws.close(); } catch {} });
  ws.addEventListener("close", () => {
    if (state.ws !== ws) return;
    state.ws = null;
    const lived = Date.now() - openedAt;
    if (lived > 5000 && state.wsRetry > 4) state.wsRetry = 0;
    startPolling("polling");
    setTimeout(() => { if (!state.ws && state.source !== "synthetic") connectStream(); }, Math.min(30000, 3000 * Math.min(state.wsRetry, 5)));
  });
}
