  if (state.pollTimer) return;
  state.pollTimer = setInterval(pollTick, 5000);
  pollTick();
}
function stopPolling() { if (state.pollTimer) { clearInterval(state.pollTimer); state.pollTimer = null; } }
async function pollTick() {
