function applyHistoryTail(candles) {
  for (const candle of candles) {
    const last = state.candles[state.candles.length - 1];
    if (!last || candle.time > last.time) state.candles.push(candle);
    else if (candle.time === last.time) state.candles[state.candles.length - 1] = candle;
  }
  state.candles.sort((a,b)=>a.time-b.time);
  state.candleByTime = new Map(state.candles.map(c => [c.time, c]));
  state.series.candle?.setData(state.candles.map(toCandleData));
  updateIndicatorSeries();
  updateVolumeSeries();
}
