export function macd(values, fast = 12, slow = 26, signalPeriod = 9) {
  const fastEma = ema(values, fast);
  const slowEma = ema(values, slow);
  const macdLine = new Array(values.length).fill(null);
  for (let i = 0; i < values.length; i++) {
    if (fastEma[i] != null && slowEma[i] != null) macdLine[i] = fastEma[i] - slowEma[i];
  }
  const signal = new Array(values.length).fill(null);
  const start = macdLine.findIndex((v) => v != null);
  if (start >= 0) {
    const slice = macdLine.slice(start);
    const cleaned = slice.map((v) => (v == null ? 0 : v));
    const sig = ema(cleaned, signalPeriod);
    for (let i = 0; i < sig.length; i++) if (sig[i] != null) signal[start + i] = sig[i];
  }
  const histogram = new Array(values.length).fill(null);
  for (let i = 0; i < values.length; i++) {
    if (macdLine[i] != null && signal[i] != null) histogram[i] = macdLine[i] - signal[i];
  }
  return { macd: macdLine, signal, histogram };
}
```
Note EMA on the slice starting at first non-null; EMA seeds at index signalPeriod-1 of slice, so signal starts at start+8. Correct.

