import { cachedJson } from "./market.js";

const CACHE_KEY = "https://cache.opentrading.internal/symbols";
const BINANCE = "https://api.binance.com";

const POPULAR = [
  "BTCUSDT",
  "ETHUSDT",
  "SOLUSDT",
  "BNBUSDT",
  "XRPUSDT",
  "DOGEUSDT",
  "ADAUSDT",
  "AVAXUSDT",
  "LINKUSDT",
  "TONUSDT",
  "DOTUSDT",
  "SUIUSDT",
  "LTCUSDT",
  "BCHUSDT",
  "TRXUSDT",
  "NEARUSDT",
  "APTUSDT",
  "ARBUSDT",
  "OPUSDT",
  "PEPEUSDT",
  "SHIBUSDT",
  "UNIUSDT",
  "ATOMUSDT",
  "FILUSDT",
  "INJUSDT",
  "SEIUSDT",
  "TIAUSDT",
  "FETUSDT",
  "WIFUSDT",
  "RNDRUSDT",
];

const STABLES = new Set([
  "USDC",
  "FDUSD",
  "TUSD",
  "BUSD",
  "DAI",
  "USDP",
  "USDD",
  "AEUR",
  "EUR",
  "GBP",
]);

const POPULAR_INDEX = new Map(POPULAR.map((symbol, index) => [symbol, index]));

const FALLBACK_SYMBOLS = POPULAR.map((symbol) => ({
  symbol,
  base: symbol.slice(0, -4),
  quote: "USDT",
}));

function toInfo(symbol, base, quote) {
  return { symbol, base, quote };
}

function sortSymbols(list) {
  return list.sort((a, b) => {
    const aIndex = POPULAR_INDEX.has(a.symbol) ? POPULAR_INDEX.get(a.symbol) : 1000;
    const bIndex = POPULAR_INDEX.has(b.symbol) ? POPULAR_INDEX.get(b.symbol) : 1000;
    if (aIndex !== bIndex) return aIndex - bIndex;
    return a.symbol.localeCompare(b.symbol);
  });
}

async function fetchExchangeInfo() {
  const response = await fetch(`${BINANCE}/api/v3/exchangeInfo`, {
    headers: { accept: "application/json", "user-agent": "OpenTrading/1.0" },
    signal: AbortSignal.timeout(9000),
  });

  if (!response.ok) throw new Error(`binance_http_${response.status}`);

  const data = await response.json();
  if (!data || !Array.isArray(data.symbols)) throw new Error("bad_exchange_info");

  const seen = new Set();
  const list = [];

  for (const item of data.symbols) {
    if (!item || item.status !== "TRADING") continue;
    if (item.quoteAsset !== "USDT") continue;
    if (item.isSpotTradingAllowed === false) continue;

    const base = String(item.baseAsset || "");
    if (!base || STABLES.has(base)) continue;
    if (/(UP|DOWN|BULL|BEAR)$/.test(base)) continue;

    const symbol = String(item.symbol || "");
    if (seen.has(symbol)) continue;

    seen.add(symbol);
    list.push(toInfo(symbol, base, "USDT"));
  }

  if (list.length < 10) throw new Error("too_few_symbols");
  return list;
}

export async function getSymbolList() {
  return cachedJson(CACHE_KEY, 3600, async () => {
    try {
      const symbols = sortSymbols(await fetchExchangeInfo());
      return { symbols, source: "binance" };
    } catch {
      return { symbols: FALLBACK_SYMBOLS.slice(), source: "fallback" };
    }
  });
}

export function searchSymbols(symbols, query, limit) {
  const normalized = String(query || "")
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "");

  if (!normalized) return symbols.slice(0, limit);

  const matches = [];

  for (const item of symbols) {
    let score = -1;

    if (item.symbol === normalized) score = 0;
    else if (item.symbol.startsWith(normalized)) score = 1;
    else if (item.base.startsWith(normalized)) score = 2;
    else if (item.symbol.includes(normalized) || item.base.includes(normalized)) score = 3;

    if (score >= 0) matches.push({ score, item });
  }

  matches.sort(
    (a, b) => a.score - b.score || a.item.symbol.localeCompare(b.item.symbol),
  );

  return matches.slice(0, limit).map((match) => match.item);
}

import { json, getCookie } from "./http.js";
import { parseSymbol } from "./market.js";

const COOKIE = "ot_sid";
const MAX_ITEMS = 50;

let schemaReady = false;

async function ensureSchema(db) {
  if (schemaReady) return;
  await db
    .prepare(
      `CREATE TABLE IF NOT EXISTS watchlist (
        sid TEXT NOT NULL,
        symbol TEXT NOT NULL,
        created_at INTEGER NOT NULL,
        PRIMARY KEY (sid, symbol)
      )`,
    )
    .run();
  schemaReady = true;
}

function cookieHeader(sid) {
  return `${COOKIE}=${sid}; Path=/; HttpOnly; SameSite=Lax; Max-Age=31536000`;
}

export async function handleWatchlist(request, env, url) {
  const path = url.pathname;
  if (!path.startsWith("/api/watchlist")) return null;

  const db = env.DB;

  if (!db) {
    // No D1 binding: the browser keeps the watchlist in localStorage.
    return request.method === "GET"
      ? json({ storage: "local", symbols: [] })
      : json({ storage: "local", ok: true });
  }

  await ensureSchema(db);

  let sid = getCookie(request, COOKIE);
  const extra = {};

  if (!sid || sid.length < 8) {
    sid = crypto.randomUUID();
    extra["set-cookie"] = cookieHeader(sid);
  }

  if (path === "/api/watchlist" && request.method === "GET") {
    const { results } = await db
      .prepare("SELECT symbol FROM watchlist WHERE sid = ? ORDER BY created_at ASC")
      .bind(sid)
      .all();

    return json(
      { storage: "d1", symbols: (results || []).map((row) => row.symbol) },
      200,
      extra,
    );
  }

  if (path === "/api/watchlist" && request.method === "POST") {
    let body;

    try {
      body = await request.json();
    } catch {
      return json({ error: "invalid_body" }, 400);
    }

    const symbol = parseSymbol(body && body.symbol);
    if (!symbol) return json({ error: "invalid_symbol" }, 400);

    const count = await db
      .prepare("SELECT COUNT(*) AS total FROM watchlist WHERE sid = ?")
      .bind(sid)
      .first();

    if (count && Number(count.total) >= MAX_ITEMS) {
      return json({ error: "watchlist_full", limit: MAX_ITEMS }, 409);
    }

    await db
      .prepare(
        "INSERT OR IGNORE INTO watchlist (sid, symbol, created_at) VALUES (?, ?, ?)",
      )
      .bind(sid, symbol, Date.now())
      .run();

    return json({ storage: "d1", ok: true, symbol }, 200, extra);
  }

  if (path.startsWith("/api/watchlist/") && request.method === "DELETE") {
    const raw = decodeURIComponent(path.slice("/api/watchlist/".length));
    const symbol = parseSymbol(raw);
    if (!symbol) return json({ error: "invalid_symbol" }, 400);

    await db
      .prepare("DELETE FROM watchlist WHERE sid = ? AND symbol = ?")
      .bind(sid, symbol)
      .run();

    return json({ storage: "d1", ok: true, symbol }, 200, extra);
  }

  return json({ error: "method_not_allowed" }, 405);
}

import { json } from "./http.js";
import {
  clampLimit,
  getHistory,
  getTicker,
  getTickers,
  parseInterval,
  parseSymbol,
} from "./market.js";
import { getSymbolList, searchSymbols } from "./symbols.js";
import { handleWatchlist } from "./watchlist.js";

function intParam(value, fallback) {
  const parsed = Number.parseInt(String(value || ""), 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function parseSymbolList(value) {
  const seen = new Set();
  const list = [];

  for (const part of String(value || "").split(",")) {
    const symbol = parseSymbol(part);
    if (symbol && !seen.has(symbol)) {
      seen.add(symbol);
      list.push(symbol);
    }
    if (list.length >= 50) break;
  }

  return list;
}

async function routeApi(request, env, url) {
  const path = url.pathname;
  const method = request.method;

  if (path === "/api/health" && method === "GET") {
    return json({
      ok: true,
      d1: Boolean(env.DB),
      now: new Date().toISOString(),
      version: "1.0.0",
    });
  }

  if (path === "/api/symbols" && method === "GET") {
    const query = url.searchParams.get("q") || "";
    const limit = Math.min(200, Math.max(1, intParam(url.searchParams.get("limit"), 60)));
    const { symbols, source } = await getSymbolList();

    return json({
      symbols: searchSymbols(symbols, query, limit),
      total: symbols.length,
      source,
    });
  }

  if (path === "/api/history" && method === "GET") {
    const symbol = parseSymbol(url.searchParams.get("symbol"));
    if (!symbol) return json({ error: "invalid_symbol" }, 400);

    const interval = parseInterval(url.searchParams.get("interval"));
    if (!interval) return json({ error: "invalid_interval" }, 400);

    const limit = clampLimit(intParam(url.searchParams.get("limit"), 600));
    return json(await getHistory(symbol, interval, limit));
  }

  if (path === "/api/ticker" && method === "GET") {
    const symbol = parseSymbol(url.searchParams.get("symbol"));
    if (!symbol) return json({ error: "invalid_symbol" }, 400);
    return json(await getTicker(symbol));
  }

  if (path === "/api/tickers" && method === "GET") {
    const symbols = parseSymbolList(url.searchParams.get("symbols"));
    if (!symbols.length) return json({ error: "invalid_symbols" }, 400);
    return json(await getTickers(symbols));
  }

  const watchlist = await handleWatchlist(request, env, url);
  if (watchlist) return watchlist;

  return json({ error: "not_found" }, 404);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname.startsWith("/api/")) {
      try {
        return await routeApi(request, env, url);
      } catch (error) {
        console.error("api_error", url.pathname, error);
        return json({ error: "internal_error" }, 500);
      }
    }

    const response = await env.ASSETS.fetch(request);

    if (response.status === 404 && request.method === "GET") {
      return env.ASSETS.fetch(
        new Request(new URL("/", url).toString(), { headers: request.headers }),
      );
    }

    return response;
  },
};

