  --bg-elevated: #ffffff;
  --panel: #ffffff;
  --panel-2: #f7f9fd;
  --panel-3: #eef2f9;
  --border: #dde3ee;
  --border-strong: #c7d0e0;
  --text: #0f172a;
  --text-muted: #5b6780;
  --text-dim: #8493ad;
  --accent: #2563eb;
  --accent-strong: #1d4ed8;
  --accent-soft: rgba(37, 99, 235, 0.1);
  --up: #0f9d8f;
  --down: #e2483f;
  --warn: #c47f10;
  --info: #1d6fd8;
  --chart-bg: #ffffff;
  --chart-grid: rgba(15, 23, 42, 0.05);
  --shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  margin: 0;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: Inter, "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  font-size: 13px;
  -webkit-font-smoothing: antialiased;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  background: none;
  border: 0;
}

button:focus-visible,
input:focus-visible,
a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

a {
  color: var(--accent);
  text-decoration: none;
}

svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.spacer {
  flex: 1;
}

.hidden {
  display: none !important;
}

/* ---------------------------------------------------------------- layout */

.app {
  display: grid;
  grid-template-rows: var(--topbar-h) minmax(0, 1fr) var(--status-h);
  height: 100dvh;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 12px;
  background: var(--bg-elevated);
  border-bottom: 1px solid var(--border);
  min-width: 0;
}

.workspace {
  display: grid;
  grid-template-columns: var(--sidebar-w) minmax(0, 1fr);
  min-height: 0;
  background: var(--bg);
}

/* ---------------------------------------------------------------- brand */

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding-right: 8px;
  color: var(--text);
  white-space: nowrap;
}

.brand-mark {
  width: 20px;
  height: 20px;
  border-radius: 6px;
  background: linear-gradient(135deg, var(--accent), #22d3ee);
  box-shadow: 0 0 18px rgba(59, 130, 246, 0.45);
}

.brand-name {
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.2px;
}

.brand-name b {
  font-weight: 700;
}

/* ---------------------------------------------------------------- controls */

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  transition: background 0.15s ease, color 0.15s ease;
}

.icon-btn:hover {
  background: var(--panel-3);
  color: var(--text);
}

.icon-btn.small {
  width: 26px;
  height: 26px;
  font-size: 18px;
  line-height: 1;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 32px;
  padding: 0 12px;
  border-radius: var(--radius-sm);
  background: var(--panel-2);
  border: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 12.5px;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.btn:hover {
  background: var(--panel-3);
  color: var(--text);
  border-color: var(--border-strong);
}

.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn.primary:hover {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.btn.wide {
  width: 100%;
  justify-content: center;
}

.symbol-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 10px;
  border-radius: var(--radius-sm);
  color: var(--text);
  min-width: 0;
}

.symbol-btn:hover {
  background: var(--panel-3);
}

.symbol-name {
  font-size: 15px;
  font-weight: 650;
  letter-spacing: -0.2px;
  white-space: nowrap;
}

.symbol-meta {
  font-size: 11px;
  color: var(--text-dim);
  white-space: nowrap;
}

.chevron {
  width: 14px;
  height: 14px;
  color: var(--text-dim);
}

.tf-group {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  border-radius: 8px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  height: 34px;
}

.tf-group button {
  height: 28px;
  min-width: 34px;
  padding: 0 8px;
  border-radius: 6px;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 500;
  transition: background 0.15s ease, color 0.15s ease;
}

.tf-group button:hover {
  background: var(--panel-3);
  color: var(--text);
}

.tf-group button.active {
  background: var(--accent-soft);
  color: var(--accent);
  font-weight: 650;
}

/* ---------------------------------------------------------------- sidebar */

.sidebar {
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: var(--panel);
  border-right: 1px solid var(--border);
}

.sidebar-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 40px;
  padding: 0 8px 0 14px;
  border-bottom: 1px solid var(--border);
}

.sidebar-head h2 {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.watchlist {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 6px;
}

.wl-row {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "symbol price"
    "symbol change";
  align-items: center;
  gap: 2px 10px;
  width: 100%;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  text-align: left;
  transition: background 0.12s ease;
}

.wl-row:hover {
  background: var(--panel-2);
}

.wl-row.active {
  background: var(--accent-soft);
  box-shadow: inset 2px 0 0 var(--accent);
}

.wl-symbol {
  grid-area: symbol;
  display: flex;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
}

.wl-base {
  font-size: 13px;
  font-weight: 650;
  letter-spacing: -0.1px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wl-quote {
  font-size: 10.5px;
  color: var(--text-dim);
}

.wl-price {
  grid-area: price;
  font-size: 12.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.wl-change {
  grid-area: change;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: var(--text-dim);
}

.wl-change.up {
  color: var(--up);
}

.wl-change.down {
  color: var(--down);
}

.wl-remove {
  position: absolute;
  top: 50%;
  right: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  margin-top: -10px;
  border-radius: 5px;
  color: var(--text-dim);
  opacity: 0;
  transition: opacity 0.12s ease, background 0.12s ease, color 0.12s ease;
}

.wl-row:hover .wl-remove {
  opacity: 1;
}

.wl-remove:hover {
  background: rgba(239, 83, 80, 0.16);
  color: var(--down);
}

.sidebar-foot {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px 14px;
  border-top: 1px solid var(--border);
  font-size: 10.5px;
  color: var(--text-dim);
}

.foot-note {
  color: var(--text-dim);
  opacity: 0.75;
}

/* ---------------------------------------------------------------- chart */

.chart-pane {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}

.chart-head {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 40px;
  padding: 0 14px;
  border-bottom: 1px solid var(--border);
  overflow: hidden;
}

.instrument {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.instrument-symbol {
  font-size: 12.5px;
  font-weight: 650;
  letter-spacing: 0.02em;
}

.instrument-tf {
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  font-size: 10.5px;
  color: var(--text-muted);
}

.source-badge {
  padding: 1px 6px;
  border-radius: 4px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--up);
  background: rgba(38, 166, 154, 0.12);
}

.source-badge.synthetic {
  color: var(--warn);
  background: rgba(245, 166, 35, 0.14);
}

.ohlc {
  display: flex;
  gap: 12px;
  font-size: 11.5px;
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
  overflow: hidden;
  white-space: nowrap;
}

.ohlc b {
  color: var(--text-muted);
  font-weight: 600;
}

.ohlc .up {
  color: var(--up);
}

.ohlc .down {
  color: var(--down);
}

.chart-host {
  position: relative;
  flex: 1;
  min-height: 0;
}

.chart {
  position: absolute;
  inset: 0;
}

.chart-loading,
.chart-error {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: color-mix(in srgb, var(--bg) 78%, transparent);
  backdrop-filter: blur(3px);
  font-size: 12.5px;
  color: var(--text-muted);
}

.chart-error {
  background: color-mix(in srgb, var(--bg) 88%, transparent);
}

.chart-error p {
  margin: 0;
  max-width: 320px;
  text-align: center;
}

.spinner {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 2px solid var(--border-strong);
  border-top-color: var(--accent);
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* ---------------------------------------------------------------- status */

.statusbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 14px;
  background: var(--bg-elevated);
  border-top: 1px solid var(--border);
  font-size: 11px;
  color: var(--text-dim);
  overflow: hidden;
  white-space: nowrap;
}

.conn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-muted);
  font-weight: 600;
  letter-spacing: 0.03em;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-dim);
}

.dot.ok {
  background: var(--up);
  box-shadow: 0 0 0 3px rgba(38, 166, 154, 0.16);
  animation: pulse 2.4s ease-in-out infinite;
}

.dot.warn {
  background: var(--warn);
  box-shadow: 0 0 0 3px rgba(245, 166, 35, 0.16);
}

.dot.idle {
  background: var(--text-dim);
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.45;
  }
}

/* ---------------------------------------------------------------- modal */

.modal {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 12vh;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(3, 6, 12, 0.62);
  backdrop-filter: blur(2px);
}

.modal-card {
  position: relative;
  width: min(560px, calc(100vw - 28px));
  max-height: 70vh;
  display: flex;
  flex-direction: column;
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  border-radius: 12px;
  box-shadow: var(--shadow);
  overflow: hidden;
  animation: modal-in 0.14s ease-out;
}

@keyframes modal-in {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.search-card {
  gap: 0;
}

.search-input-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
}

.search-input-wrap svg {
  color: var(--text-dim);
  flex: none;
}

.search-input-wrap input {
  flex: 1;
  min-width: 0;
  border: 0;
  background: none;
  outline: none;
  font-size: 14px;
}

.search-input-wrap input::placeholder {
  color: var(--text-dim);
}

.search-input-wrap kbd {
  padding: 2px 6px;
  border-radius: 4px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  font-family: inherit;
  font-size: 10px;
  color: var(--text-dim);
}

.search-results {
  overflow-y: auto;
  padding: 6px;
  min-height: 120px;
}

.search-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  padding: 9px 10px;
  border-radius: var(--radius-sm);
  text-align: left;
}

.search-row:hover,
.search-row.active {
  background: var(--panel-3);
}

.search-symbol {
  font-weight: 650;
  font-size: 13px;
}

.search-symbol span {
  color: var(--text-dim);
  font-weight: 500;
}

.search-full {
  font-size: 11px;
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
}

.search-empty {
  padding: 26px 14px;
  text-align: center;
  color: var(--text-dim);
  font-size: 12px;
}

.indicators-card {
  padding: 16px;
  gap: 10px;
}

.indicators-card h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 650;
}

.hint {
  margin: 0 0 4px;
  font-size: 11.5px;
  color: var(--text-dim);
}

.ind-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow-y: auto;
  margin-bottom: 6px;
}

.ind-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 12.5px;
}

.ind-row:hover {
  background: var(--panel-2);
}

.ind-row input {
  width: 15px;
  height: 15px;
  accent-color: var(--accent);
  cursor: pointer;
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 44px;
  z-index: 60;
  transform: translateX(-50%);
  padding: 9px 14px;
  border-radius: 8px;
  background: var(--panel-3);
  border: 1px solid var(--border-strong);
  box-shadow: var(--shadow);
  font-size: 12px;
  color: var(--text);
}

/* ---------------------------------------------------------------- scrollbars */

* {
  scrollbar-width: thin;
  scrollbar-color: var(--border-strong) transparent;
}

*::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

*::-webkit-scrollbar-thumb {
  background: var(--border-strong);
  border-radius: 8px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

/* ---------------------------------------------------------------- responsive */

.only-mobile {
  display: none;
}

@media (max-width: 900px) {
  :root {
    --sidebar-w: 270px;
  }

  .only-mobile {
    display: inline-flex;
  }

  .brand-name {
    display: none;
  }

  .workspace {
    grid-template-columns: minmax(0, 1fr);
  }

  .sidebar {
    position: fixed;
    top: var(--topbar-h);
    bottom: var(--status-h);
    left: 0;
    z-index: 30;
    width: var(--sidebar-w);
    transform: translateX(-102%);
    transition: transform 0.2s ease;
    box-shadow: var(--shadow);
  }

  .sidebar.open {
    transform: none;
  }

  .symbol-meta,
  .chevron {
    display: none;
  }

  .symbol-name {
    font-size: 14px;
  }

  .btn span {
    display: none;
  }

  .tf-group button {
    min-width: 30px;
    padding: 0 6px;
  }

  .ohlc {
    display: none;
  }
}

@media (max-width: 520px) {
  .topbar {
    gap: 6px;
    padding: 0 8px;
  }

  .symbol-btn {
    padding: 0 6px;
  }

  .tf-group button {
    min-width: 27px;
    padding: 0 4px;
    font-size: 11px;
  }

  .statusbar {
    gap: 10px;
    font-size: 10px;
  }

  #statusSource {
    display: none;
  }
}

