  const candleSeries = chart.addSeries(LC.CandlestickSeries, { ... });
  state.series.candle = candleSeries;

  const digits = precisionFor(state.candles[state.candles.length - 1].close);
  candleSeries.applyOptions({ priceFormat: { type: "price", precision: digits, minMove: 1 / 10 ** digits } });
  candleSeries.setData(state.candles.map(toCandleData));

  buildIndicatorSeries(chart, colors);

  chart.timeScale().setVisibleLogicalRange({
    from: Math.max(0, state.candles.length - 160),
    to: state.candles.length + 4,
  });

