  const times = state.candles.map((c) => c.time);
  const closes = state.candles.map((c) => c.close);
  const s = state.series;
  let pane = 1;

  if (state.indicators.volume) {
    const volume = chart.addSeries(LC.HistogramSeries, {
      priceScaleId: "",
      priceFormat: { type: "volume" },
      priceLineVisible: false,
      lastValueVisible: false,
    });
    volume.priceScale().applyOptions({ scaleMargins: { top: 0.82, bottom: 0 } });
    volume.setData(state.candles.map((c) => ({
      time: c.time,
      value: c.volume || 0,
      color: c.close >= c.open ? VOL_UP : VOL_DOWN,
    })));
    s.volume = volume;
  }

  const addLine = (color, width, title, paneIndex = 0, lineStyle = LC.LineStyle.Solid) => chart.addSeries(LC.LineSeries, {
    color, lineWidth: width, title, lineStyle,
    priceLineVisible: false, lastValueVisible: false, crosshairMarkerVisible: false,
  }, paneIndex);

  if (state.indicators.sma20) { s.sma20 = addLine(colors.info, 2, "SMA 20"); s.sma20.setData(lineData(times, sma(closes, 20))); }
  if (state.indicators.sma50) { s.sma50 = addLine(colors.warn, 2, "SMA 50"); ... }
  if (state.indicators.ema50) { s.ema50 = addLine(colors.accent, 2, "EMA 50"); ... }

  if (state.indicators.bb) {
    const bands = bollinger(closes, 20, 2);
    s.bbUpper = addLine(colors.info, 1, "BB upper");
    s.bbLower = addLine(colors.info, 1, "BB lower");
    s.bbMiddle = addLine(colors.muted, 1, "BB basis", 0, LC.LineStyle.Dotted);
    s.bbUpper.setData(lineData(times, bands.upper));
    ...
  }

  if (state.indicators.rsi) {
    s.rsi = addLine(colors.rsi, 2, "RSI 14", pane);
    s.rsi.setData(lineData(times, rsi(closes, 14)));
    s.rsi.applyOptions({ autoscaleInfoProvider: () => ({ priceRange: { minValue: 0, maxValue: 100 } }) });
    s.rsi.createPriceLine({ price: 70, color: colors.border, lineWidth: 1, lineStyle: LC.LineStyle.Dashed, axisLabelVisible: false, title: "" });
    s.rsi.createPriceLine({ price: 30, ... });
    pane += 1;
  }

  if (state.indicators.macd) {
    const result = macd(closes, 12, 26, 9);
    s.macdHist = chart.addSeries(LC.HistogramSeries, { priceLineVisible: false, lastValueVisible: false }, pane);
    s.macdHist.setData(histogramData(times, result.histogram));
    s.macd = addLine(colors.info, 2, "MACD", pane);
    s.macdSignal = addLine(colors.warn, 2, "Signal", pane);
    s.macd.setData(lineData(times, result.macd));
    s.macdSignal.setData(lineData(times, result.signal));
    pane += 1;
  }

  const panes = chart.panes();
  if (panes.length > 1) {
    const hasRsi = Boolean(state.indicators.rsi);
    const hasMacd = Boolean(state.indicators.macd);
    if (hasRsi) panes[1].setHeight(112);
    if (hasMacd) {
      const index = hasRsi ? 2 : 1;
      if (panes[index]) panes[index].setHeight(132);
    }
  }
}
