```js
function applyKline(kline) {
  const time = Math.floor(Number(kline.t) / 1000);
  const candle = {
    time,
    open: Number(kline.o),
    high: Number(kline.h),
    low: Number(kline.l),
    close: Number(kline.c),
    volume: Number(kline.v),
  };
  if (!Number.isFinite(candle.close)) return;

  const candles = state.candles;
  const last = candles[candles.length - 1];

  if (!last || time > last.time) {
    candles.push(candle);
    if (candles.length > 1200) candles.shift();
  } else if (time === last.time) {
    candles[candles.length - 1] = candle;
  } else {
    return;
  }

  state.candleByTime.set(time, candle);
  const s = state.series;
  if (s.candle) s.candle.update(candle);
  if (s.volume) s.volume.update({ time, value: candle.volume, color: candle.close >= candle.open ? VOL_UP : VOL_DOWN });
  updateIndicators();
  setOhlc(candle);
  updateConnectionPrice(candle.close);
}
