function connectStream() {
  disconnectStream();
  if (!state.candles.length) return;
  if (state.source !== "binance") { startPolling(); return; }
  const stream = `${state.symbol.toLowerCase()}@kline_${state.interval}`;
  const base = "wss://stream.binance.com";
  const attempt = state.wsAttempt % 2;
  state.wsAttempt += 1;
  const url = attempt === 0 ? `${base}:9443/ws/${stream}` : `${base}/ws/${stream}`;
  setConn("connecting");
  let socket;
  try { socket = new WebSocket(url); } catch { startPolling(); return; }
  state.ws = socket;
  const openedAt = Date.now();

  socket.addEventListener("open", () => { if (state.ws === socket) { setConn("live"); stopPolling(); } });
  socket.addEventListener("message", (event) => { ... });
  socket.addEventListener("error", () => { try { socket.close(); } catch {} });
  socket.addEventListener("close", () => {
    if (state.ws !== socket) return;
    state.ws = null;
    startPolling();
    scheduleReconnect(Date.now() - openedAt > 10000 ? 4000 : 20000);
  });
}
```
