async function pollTick() {
  try {
    const data = await getJson(`/api/history?symbol=${state.symbol}&interval=${state.interval}&limit=3`);
    if (data.source !== state.source) { state.source = data.source; updateSourceBadge(); }
    applyTail(data.candles);
