}

function applyTail(candles) {
  if (!Array.isArray(candles) || !candles.length) return;
  const normalized = candles.map(normalizeCandle);
  const latest = normalized[normalized.length - 1];
  const last = state.candles[state.candles.length - 1];
  if (!last || latest.time > last.time) {
    for (const candle of normalized) if (!state.candles.some((c) => c.time === candle.time)) state.candles.push(candle);
    state.candles.sort((a, b) => a.time - b.time);
  } else {
    for (const candle of normalized) {
      const index = state.candles.findIndex((c) => c.time === candle.time);
      if (index >= 0) state.candles[index] = candle;
    }
  }
  state.candleByTime = new Map(state.candles.map((c) => [c.time, c]));
  state.series.candle?.setData(state.candles.map(toCandleData));
  updateIndicators();
  setOhlc(latest);
  updateConnectionPrice(latest.close);
}
