function onKeyDown(event) {
  if (event.key === "Escape") { closeSearch(); closeIndicatorsModal(); return; }
  if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); openSearch(); return; }
  if (el.searchModal.classList.contains("hidden")) return;
  if (event.key === "ArrowDown") { event.preventDefault(); searchIndex = Math.min(searchResults.length - 1, searchIndex + 1); renderSearchResults(); return; }
  if (event.key === "ArrowUp") { event.preventDefault(); searchIndex = Math.max(0, searchIndex - 1); renderSearchResults(); return; }
  if (event.key === "Enter" && searchResults[searchIndex]) { event.preventDefault(); chooseSearchResult(searchResults[searchIndex].symbol); }
}
