import http from "node:http";
import fs from "node:fs/promises";
import path from "node:path";
import handler from "./src/index.js";

const publicDir = path.resolve("./public");
const types = { ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8", ".svg": "image/svg+xml", ".json": "application/json" };

const env = {
  ASSETS: {
    async fetch(request) {
      const url = new URL(request.url);
      let file = url.pathname === "/" ? "/index.html" : url.pathname;
      try {
        const data = await fs.readFile(path.join(publicDir, file));
        const type = types[path.extname(file)] || "application/octet-stream";
        return new Response(data, { status: 200, headers: { "content-type": type } });
      } catch {
        // SPA fallback
        try {
          const data = await fs.readFile(path.join(publicDir, "index.html"));
          return new Response(data, { status: url.pathname.startsWith("/api/") ? 404 : 200, headers: { "content-type": types[".html"] } });
        } catch { return new Response("not found", { status: 404 }); }
      }
    },
  },
};

const server = http.createServer(async (req, res) => {
  const origin = `http://${req.headers.host}`;
  const url = new URL(req.url, origin);
  const body = req.method === "GET" || req.method === "HEAD" ? undefined : await readBody(req);
  const request = new Request(url, { method: req.method, headers: req.headers, body });
  const response = await handler.fetch(request, env);
  res.statusCode = response.status;
  response.headers.forEach((v, k) => res.setHeader(k, v));
  const buffer = Buffer.from(await response.arrayBuffer());
  res.end(buffer);
});
server.listen(8787, () => console.log("http://localhost:8787"));
```
