import http from "node:http";
import fs from "node:fs/promises";
import path from "node:path";
import handler from "./src/index.js";

const publicDir = path.resolve("./public");

const types = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".svg": "image/svg+xml",
  ".json": "application/json; charset=utf-8",
  ".ico": "image/x-icon",
  ".png": "image/png",
  ".woff2": "font/woff2",
};

const env = {
  ASSETS: {
    async fetch(request) {
      const url = new URL(request.url);
      const file = url.pathname === "/" ? "/index.html" : url.pathname;

      try {
        const data = await fs.readFile(path.join(publicDir, file));
        return new Response(data, {
          status: 200,
          headers: { "content-type": types[path.extname(file)] || "application/octet-stream" },
        });
      } catch {
        if (url.pathname.startsWith("/api/")) return new Response("not found", { status: 404 });
        const data = await fs.readFile(path.join(publicDir, "index.html"));
        return new Response(data, {
          status: 200,
          headers: { "content-type": types[".html"] },
        });
      }
    },
  },
};

function readBody(request) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    request.on("data", (chunk) => chunks.push(chunk));
    request.on("end", () => resolve(Buffer.concat(chunks)));
    request.on("error", reject);
  });
}

const server = http.createServer(async (request, response) => {
  try {
    const origin = `http://${request.headers.host || "localhost:8787"}`;
    const url = new URL(request.url, origin);
    const hasBody = request.method !== "GET" && request.method !== "HEAD";
    const body = hasBody ? await readBody(request) : undefined;

    const apiRequest = new Request(url, {
      method: request.method,
      headers: request.headers,
      body,
    });

    const apiResponse = await handler.fetch(apiRequest, env);
    response.statusCode = apiResponse.status;

    apiResponse.headers.forEach((value, key) => {
      if (key.toLowerCase() !== "content-encoding") response.setHeader(key, value);
    });

    const buffer = Buffer.from(await apiResponse.arrayBuffer());
    response.end(buffer);
  } catch (error) {
    console.error("server_error", error);
    response.statusCode = 500;
    response.end(String(error));
  }
});

server.listen(8787, "127.0.0.1", () => {
  console.log("OpenTrading dev server: http://127.0.0.1:8787");
});

