198: /* --------------------------------------------------------------------------
199:  * Deterministic synthetic fallback.
200:  * Used when Binance is unreachable (region blocks, rate limits, outages).
201:  * Prices are a smooth function of time, so refetching the same candle always
202:  * returns the same value and the chart never "jumps".
203:  * ------------------------------------------------------------------------ */
204: 
205: function hash(text) {
206:   let value = 2166136261;
207:   for (let i = 0; i < text.length; i++) {
208:     value ^= text.charCodeAt(i);
209:     value = Math.imul(value, 16777619);
210:   }
211:   return value >>> 0;
212: }
213: 
214: function noise(seed) {
215:   return (hash(seed) % 2000) / 1000 - 1;
216: }
217: 
218: function basePrice(symbol) {
219:   return BASE_PRICES[symbol] ?? 0.5 + (hash(symbol) % 5000) / 100;
220: }
221: 
222: function priceAt(symbol, seconds) {
223:   const base = basePrice(symbol);
224:   const phase = (hash(`${symbol}:phase`) % 628) / 100;
225:   const daily = Math.sin((seconds / 86400) * Math.PI * 2 + phase) * 0.035;
226:   const hourly = Math.sin((seconds / 3600) * Math.PI * 2 + phase * 1.7) * 0.012;
227:   const fast = Math.sin((seconds / 300) * Math.PI * 2 + phase * 2.3) * 0.004;
228:   const jitter = noise(`${symbol}:${Math.floor(seconds / 60)}`) * 0.0015;
229: 
230:   return base * (1 + daily + hourly + fast + jitter);
231: }
232: 
233: function roundPrice(value) {
234:   if (value >= 1000) return Math.round(value * 100) / 100;
235:   if (value >= 1) return Math.round(value * 10000) / 10000;
236:   return Math.round(value * 1e8) / 1e8;
237: }
238: 
239: function syntheticHistory(symbol, interval, limit) {
240:   const stepMs = INTERVALS[interval];
241:   const stepSec = stepMs / 1000;
242:   const end = Math.floor(Date.now() / stepMs) * stepMs;
243:   const candles = [];
244: 
245:   for (let i = limit - 1; i >= 0; i--) {
246:     const time = Math.floor((end - i * stepMs) / 1000);
247:     const open = priceAt(symbol, time);
248:     const close = priceAt(symbol, time + stepSec);
249:     const wick = 0.0008 + ((hash(`${symbol}:w${time}`) % 1000) / 1000) * 0.0025;
250:     const high = Math.max(open, close) * (1 + wick);
251:     const low = Math.min(open, close) * (1 - wick * 0.9);
252:     const volume = 50 + (hash(`${symbol}:v${time}`) % 100000) / 100;
253: 
254:     candles.push({
255:       time,
256:       open: roundPrice(open),
257:       high: roundPrice(high),
258:       low: roundPrice(low),
259:       close: roundPrice(close),
260:       volume: Math.round(volume),
261:     });
262:   }
263: 
264:   return candles;
265: }
266: 
267: function syntheticTicker(symbol) {
268:   const now = Math.floor(Date.now() / 1000);
269:   const price = priceAt(symbol, now);
270:   const dayAgo = priceAt(symbol, now - 86400);
271:   let high = price;
272:   let low = price;
273: 
274:   for (let i = 0; i <= 24; i++) {
275:     const sample = priceAt(symbol, now - i * 3600);
276:     if (sample > high) high = sample;
277:     if (sample < low) low = sample;
278:   }
279: 
280:   return {
281:     price: roundPrice(price),
282:     changePct: Math.round((price / dayAgo - 1) * 10000) / 100,
283:     high: roundPrice(high),
284:     low: roundPrice(low),
285:     volume: Math.round(50000 + (hash(`${symbol}:${now}`) % 900000)),
286:   };
287: }

