    const sleep = (ms) => new Promise(r => setTimeout(r, ms));
    const waitFor = async (fn, timeout = 12000) => {
      const start = Date.now();
      while (Date.now() - start < timeout) { if (fn()) return true; await sleep(100); }
      return false;
    };
    const started = Date.now();
    const loaded = await waitFor(() => document.getElementById("chartLoading").classList.contains("hidden"));
    await sleep(1200);
    const resp = await fetch("/api/health");
    return {
      loaded,
      ms: Date.now() - started,
      health: await resp.json(),
      headers: [...resp.headers].filter(([k]) => k.startsWith("x-") || k === "referrer-policy"),
